//! 🧪️ Shared neutral declaration domains execute under each version's own catalog type.
use super::*;
use super::super::DetailsTestProfile;
fn fixture()->DslValue{semio_framework_pack_json::to_dsl_value(&semio_framework_pack_json::parse(include_str!("../📚️catalog/⚖️domain/🧪️tests/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap())}
fn text<'a>(value:&'a DslValue,key:&str)->&'a str{value.get(key).unwrap().as_str().unwrap()}
fn expression(value:&DslValue)->IfcTypeExpression{IfcTypeExpression{kind:text(value,"kind").into(),name:value.get("name").and_then(DslValue::as_str).map(str::to_owned),width:value.get("width").and_then(DslValue::as_i64),fixed:value.get("fixed").and_then(DslValue::as_bool).unwrap_or(false),aggregate:value.get("aggregate").and_then(DslValue::as_str).map(str::to_owned),lower:value.get("lower").and_then(DslValue::as_i64),upper:value.get("upper").and_then(DslValue::as_i64),unique:value.get("unique").and_then(DslValue::as_bool).unwrap_or(false),optional:value.get("optional").and_then(DslValue::as_bool).unwrap_or(false),item:value.get("item").map(expression).map(Box::new),..Default::default()}}
fn value(value:&DslValue)->IfcValue{let payload=value.get("value");match text(value,"kind"){"unset"=>IfcValue::Unset,"derived"=>IfcValue::Derived,"string"=>IfcValue::String(payload.unwrap().as_str().unwrap().into()),"enum"=>IfcValue::Enum(payload.unwrap().as_str().unwrap().into()),"binary"=>IfcValue::Binary(payload.unwrap().as_str().unwrap().into()),"integer"=>IfcValue::Integer(payload.unwrap().as_str().unwrap().parse().unwrap()),"reference"=>IfcValue::Reference(payload.unwrap().as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(u64::from_str_radix(payload.unwrap().as_str().unwrap(),16).unwrap())),"aggregate"=>IfcValue::Aggregate(payload.unwrap().as_array().unwrap().iter().map(self::value).collect()),"typedValue"=>{let typed=payload.unwrap();IfcValue::TypedValue(IfcTypedValue{name:text(typed,"name").into(),items:typed.get("items").unwrap().as_array().unwrap().iter().map(self::value).collect()})},_=>panic!("Unknown neutral value")}}
#[test]
fn strict_neutral_domains_and_original_callback_boundaries(){let fixture=fixture();for row in fixture.get("cases").unwrap().as_array().unwrap(){let expression=expression(row.get("expression").unwrap());let value=value(row.get("value").unwrap());let reference=|id:u64,expected:&str,tick:&mut dyn FnMut()->Result<(),String>|{for target in fixture.get("targets").unwrap().as_array().unwrap(){tick()?;if text(target,"id").parse::<u64>().unwrap()==id{return Ok(target.get("types").unwrap().as_array().unwrap().iter().any(|name|DetailsTestProfile::catalog().is_subtype(name.as_str().unwrap(),expected)));}}Ok(false)};let mut ticks=0;let mut tick=||{ticks+=1;Ok(())};let admitted=domain::check_value(DetailsTestProfile::catalog(),&expression,&value,false,true,&mut domain::DomainControl{tick:&mut tick,reference:&mut {reference}}).is_ok();assert_eq!(admitted,row.get("admitted").unwrap().as_bool().unwrap(),"{}",text(row,"name"));for stop in 1..=ticks{let mut count=0;let mut tick=||{count+=1;if count==stop{Err("original-cancel".into())}else{Ok(())}};let result=domain::check_value(DetailsTestProfile::catalog(),&expression,&value,false,true,&mut domain::DomainControl{tick:&mut tick,reference:&mut {reference}});assert_eq!(result.unwrap_err(),"original-cancel");}}}
#[test]
fn neutral_repairs_preserve_invalid_siblings_and_reject_worsened_ancestors(){let fixture=fixture();for row in fixture.get("repairs").unwrap().as_array().unwrap(){let values=|key:&str|IfcValue::Aggregate(row.get(key).unwrap().as_array().unwrap().iter().map(|value|match value.as_str().unwrap(){"invalid"=>IfcValue::String("invalid".into()),text=>IfcValue::Integer(text.parse().unwrap())}).collect());let expression=IfcTypeExpression{kind:"aggregate".into(),aggregate:Some(text(row,"aggregate").into()),lower:row.get("lower").and_then(DslValue::as_i64),upper:row.get("upper").and_then(DslValue::as_i64),item:Some(Box::new(IfcTypeExpression{kind:"named".into(),name:Some("INTEGER".into()),..Default::default()})),..Default::default()};let route:Vec<_>=row.get("route").unwrap().as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).collect();let operation=match text(row,"operation"){"insert"=>domain::ValueChange::Insert,"remove"=>domain::ValueChange::Remove,"move"=>domain::ValueChange::Move,_=>domain::ValueChange::Set};let mut tick=||Ok(());let mut reference=|_:u64,_:&str,_:&mut dyn FnMut()->Result<(),String>|Ok(false);assert_eq!(domain::check_change(DetailsTestProfile::catalog(),&expression,&values("before"),&values("after"),&route,operation,false,&mut domain::DomainControl{tick:&mut tick,reference:&mut reference}).is_ok(),row.get("admitted").unwrap().as_bool().unwrap(),"{}",text(row,"name"));}}

#[test]
fn resumable_native_cursor_consumes_every_neutral_domain_and_repair_vector(){let fixture=fixture();let population=IfcSnapshot{entities:fixture.get("targets").unwrap().as_array().unwrap().iter().map(|target|{let names=target.get("types").unwrap().as_array().unwrap();IfcEntity{id:text(target,"id").parse().unwrap(),name:names[0].as_str().unwrap().into(),args:Vec::new(),complex:names[1..].iter().map(|name|IfcComplexType{name:name.as_str().unwrap().into(),args:Vec::new()}).collect()}}).collect(),..Default::default()};for row in fixture.get("cases").unwrap().as_array().unwrap(){let expression=Box::leak(Box::new(expression(row.get("expression").unwrap())));let value=value(row.get("value").unwrap());let mut cursor=domain_cursor::DomainCursor::default();cursor.start(expression,&[],domain::ValueChange::Set,false,true,false).unwrap();let mut completed=false;let mut admitted=true;for _ in 0..100_000{match cursor.advance(DetailsTestProfile::catalog(),&IfcValue::Unset,&value,&population){Ok(true)=>{completed=true;break;},Ok(false)=>{},Err(_)=>{admitted=false;completed=true;break;}}}assert!(completed,"{} did not terminate",text(row,"name"));assert_eq!(admitted,row.get("admitted").unwrap().as_bool().unwrap(),"{}",text(row,"name"));cursor.clear();}for row in fixture.get("repairs").unwrap().as_array().unwrap(){let values=|key:&str|IfcValue::Aggregate(row.get(key).unwrap().as_array().unwrap().iter().map(|value|match value.as_str().unwrap(){"invalid"=>IfcValue::String("invalid".into()),text=>IfcValue::Integer(text.parse().unwrap())}).collect());let expression=Box::leak(Box::new(IfcTypeExpression{kind:"aggregate".into(),aggregate:Some(text(row,"aggregate").into()),lower:row.get("lower").and_then(DslValue::as_i64),upper:row.get("upper").and_then(DslValue::as_i64),item:Some(Box::new(IfcTypeExpression{kind:"named".into(),name:Some("INTEGER".into()),..Default::default()})),..Default::default()}));let route:Vec<_>=row.get("route").unwrap().as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).collect();let operation=match text(row,"operation"){"insert"=>domain::ValueChange::Insert,"remove"=>domain::ValueChange::Remove,"move"=>domain::ValueChange::Move,_=>domain::ValueChange::Set};let before=values("before");let after=values("after");let mut cursor=domain_cursor::DomainCursor::default();cursor.start(expression,&route,operation,false,false,false).unwrap();let mut completed=false;let mut admitted=true;for _ in 0..100_000{match cursor.advance(DetailsTestProfile::catalog(),&before,&after,&population){Ok(true)=>{completed=true;break;},Ok(false)=>{},Err(_)=>{admitted=false;completed=true;break;}}}assert!(completed);assert_eq!(admitted,row.get("admitted").unwrap().as_bool().unwrap(),"{}",text(row,"name"));}}

#[test]
fn resumable_unique_waits_for_complete_numeric_and_text_equality(){for strings in [false,true]{let expression=Box::leak(Box::new(IfcTypeExpression{kind:"aggregate".into(),aggregate:Some("SET".into()),item:Some(Box::new(IfcTypeExpression{kind:"named".into(),name:Some(if strings{"STRING"}else{"NUMBER"}.into()),..Default::default()})),..Default::default()}));let value=if strings{IfcValue::Aggregate(vec![IfcValue::String("same 😀 long text".into()),IfcValue::String("same 😀 long text".into())])}else{IfcValue::Aggregate(vec![IfcValue::Integer(1),IfcValue::Real(1.0)])};let mut cursor=domain_cursor::DomainCursor::default();cursor.start(expression,&[],domain::ValueChange::Set,false,true,false).unwrap();let population=IfcSnapshot::default();let mut refused=false;let mut turns=0;for _ in 0..4096{turns+=1;match cursor.advance(DetailsTestProfile::catalog(),&IfcValue::Unset,&value,&population){Err(reason)=>{assert_eq!(reason,"ifc-domain-unique");refused=true;break;},Ok(true)=>panic!("resumable duplicate escaped uniqueness"),Ok(false)=>{}}}assert!(turns>16);assert!(refused);}}
